<template><section class="ops-panel"><div class="ops-toolbar"><div><h2>官方知识库</h2><p class="ops-muted">维护公开的文本或问答条目。已发布版本只读，复制后编辑，再独立审批发布。</p></div><div class="ops-actions"><el-button v-if="can('official.resource.write')" size="small" @click="edit()">新建知识库草稿</el-button><el-button size="small" @click="load">刷新</el-button></div></div><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-table :data="rows" v-loading="loading"><el-table-column prop="name" label="知识库" min-width="160" /><el-table-column prop="ragModelId" label="知识库模型" min-width="160" /><el-table-column prop="version" label="版本" width="90" /><el-table-column prop="reviewStatus" label="状态" width="120" /><el-table-column label="操作" min-width="260"><template slot-scope="s"><el-button v-if="can('official.resource.write') && s.row.reviewStatus === 'DRAFT'" type="text" @click="edit(s.row)">编辑</el-button><el-button v-if="can('official.resource.write')" type="text" :disabled="busy" @click="clone(s.row)">复制版本</el-button><el-button v-if="can('official.resource.publish') && s.row.reviewStatus === 'DRAFT' && !approvalFor(s.row)" type="text" :disabled="busy" @click="requestApproval(s.row)">申请发布</el-button><el-button v-if="approvalFor(s.row) && approvalFor(s.row).status === 'APPROVED'" type="text" :disabled="busy" @click="publish(s.row)">发布批准版本</el-button><el-tag v-else-if="approvalFor(s.row)" size="mini">等待审批</el-tag></template></el-table-column></el-table><el-dialog title="官方知识库草稿" :visible.sync="visible" width="min(760px,94vw)" :close-on-click-modal="false"><el-form label-width="100px"><el-form-item label="名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="说明"><el-input v-model="form.description" /></el-form-item><el-form-item label="知识库模型"><el-input v-model="form.ragModelId" placeholder="已配置的本地知识库模型 ID" /></el-form-item><div v-for="(entry,index) in form.entries" :key="index" class="knowledge-entry"><div class="ops-toolbar"><strong>条目 {{ index+1 }}</strong><el-button type="text" @click="form.entries.splice(index,1)">删除条目</el-button></div><el-form-item label="问题"><el-input v-model="entry.question" /></el-form-item><el-form-item label="答案"><el-input v-model="entry.answer" type="textarea" :rows="3" /></el-form-item><el-form-item label="或文本内容"><el-input v-model="entry.content" type="textarea" :rows="4" /></el-form-item></div><el-button @click="form.entries.push({question:'',answer:'',content:''})">添加条目</el-button></el-form><el-alert v-if="saveError" :title="saveError" type="error" :closable="false" /><span slot="footer"><el-button :disabled="busy" @click="visible=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存草稿</el-button></span></el-dialog></section></template>
<script>
import { platformRequest } from '@/apis/platform';
import { hasPermission } from '@/security/session';
export default {data(){return{rows:[],approvals:[],loading:false,busy:false,error:'',visible:false,saveError:'',form:{entries:[]}};},created(){this.load();},methods:{can(permission){return hasPermission(this.$store.state.userInfo,permission);},async load(){this.loading=true;this.error='';try{const [rows,approvals]=await Promise.all([platformRequest('GET','/ops/content/knowledge'),this.can('official.resource.publish')?platformRequest('GET','/ops/approvals'):[]]);this.rows=rows.map(row=>({...row,reviewStatus:row.scope==='OFFICIAL'?'APPROVED':'DRAFT'}));this.approvals=approvals;}catch(error){this.error=error.message;}finally{this.loading=false;}},approvalFor(row){return this.approvals.find(item=>item.action==='official.resource.publish'&&String(item.targetId)===String(row.id)&&String(item.version)===String(row.version)&&item.requesterId===this.$store.state.userInfo.employeeId&&['PENDING','APPROVED'].includes(item.status)&&new Date(item.expiresAt).getTime()>Date.now());},async edit(row={}){this.saveError='';try{const detail=row.id?await platformRequest('GET','/ops/content/knowledge/'+encodeURIComponent(row.id)):row;this.form={id:detail.id,name:detail.name||'',description:detail.description||'',ragModelId:detail.ragModelId||'',entries:(detail.entries||[{question:'',answer:'',content:''}]).map(entry=>({question:entry.question||'',answer:entry.answer||'',content:entry.content||''}))};this.visible=true;}catch(error){this.$message.error(error.message);}},async save(){if(this.busy)return;if(!this.form.name.trim()||!this.form.ragModelId.trim()||!this.form.entries.length||this.form.entries.some(entry=>!entry.content.trim()&&(!entry.question.trim()||!entry.answer.trim()))){this.saveError='填写名称、模型及条目；每条需完整问答或文本内容';return;}this.busy=true;this.saveError='';try{await platformRequest(this.form.id?'PUT':'POST','/ops/content/knowledge'+(this.form.id?'/'+encodeURIComponent(this.form.id):''),{name:this.form.name,description:this.form.description,ragModelId:this.form.ragModelId,entries:this.form.entries});this.visible=false;await this.load();}catch(error){this.saveError=error.message;}finally{this.busy=false;}},async clone(row){this.busy=true;try{await platformRequest('POST',`/ops/content/knowledge/${encodeURIComponent(row.id)}/clone`);await this.load();}catch(error){this.$message.error(error.message);}finally{this.busy=false;}},async requestApproval(row){this.busy=true;try{const proposal=await platformRequest('GET',`/ops/content/knowledge/${encodeURIComponent(row.id)}/prepare`);await platformRequest('POST','/ops/approvals',proposal);await this.load();}catch(error){this.$message.error(error.message);}finally{this.busy=false;}},async publish(row){const approval=this.approvalFor(row);if(this.busy||approval?.status!=='APPROVED')return;this.busy=true;try{await platformRequest('POST',`/ops/content/knowledge/${encodeURIComponent(row.id)}/publish`,{},{headers:{'X-Ops-Approval-Id':approval.id}});await this.load();}catch(error){this.$message.error(error.message);}finally{this.busy=false;}}}};
</script>
<style scoped>.knowledge-entry{padding:18px;margin:12px 0;border:1px solid #e1e8f0;border-radius:8px}</style>
